const D = { energy: .62, scale: 1, speed: 1, density: .5, firing: .6, hue: 145, x: .5, y: .5, style: 'fluor', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// -----------------------------------------------------------------------------
// Neurons under the objective, drawn the way a calcium-imaging or Golgi-stain
// preparation shows them. Each cell is a soma with a nucleus, a recursively
// branching dendritic arbor that tapers and forks to fine tips studded with
// spines, and one long axon trailing terminal boutons. The cells FIRE: a wave of
// brightness -- a back-propagating action potential / calcium transient -- keeps
// sweeping outward from every soma along its arbor, and a spike runs the axon,
// flashing each synaptic bouton as it passes. The waves run on incommensurate
// rates per cell so the firing never re-phases; a faint out-of-focus neuropil of
// background processes fills the field and drifts. Offered as GCaMP fluorescence,
// a sepia Golgi silver stain, electric neon, or a connectome schematic.
// -----------------------------------------------------------------------------

const u = Math.min(width, height);
const sp = 0.25 + P.speed * 0.9;
const fireRate = 0.5 + P.firing * 1.6;

const sd = (P.seed | 0);
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7 + 3.7) * 43758.5453; return s - Math.floor(s); };

const nCell = Math.round(3 + P.density * 5);
if (!S.cells || S.seedUsed !== P.seed || S.nUsed !== nCell) {
  S.seedUsed = P.seed; S.nUsed = nCell;
  S.cells = [];
  S.maxDist = 1;
  for (let k = 0; k < nCell; k++) {
    let kk = k * 100;
    const rk = () => fr(kk++);
    const segs = [];        // {x1,y1,x2,y2,w,d0,d1}
    const boutons = [];     // axon path points {x,y,d}
    let maxd = 0.001;
    // recursive dendrite growth in soma-local units (~ unit radius)
    let budget = 60;
    function grow(x, y, ang, len, wdt, depth, dist) {
      if (depth > 4 || budget <= 0) return;
      const steps = 2 + (depth < 2 ? 1 : 0);
      let cx = x, cy = y, cd = dist;
      for (let s2 = 0; s2 < steps && budget > 0; s2++) {
        ang += (rk() - 0.5) * 0.9;
        const nx = cx + Math.cos(ang) * len, ny = cy + Math.sin(ang) * len;
        const nd = cd + len;
        segs.push({ x1: cx, y1: cy, x2: nx, y2: ny, w: wdt, d0: cd, d1: nd });
        budget--;
        if (nd > maxd) maxd = nd;
        cx = nx; cy = ny; cd = nd;
      }
      // fork
      const nb = depth < 3 ? (rk() < 0.85 ? 2 : 1) : (rk() < 0.4 ? 1 : 0);
      for (let b = 0; b < nb; b++) {
        const da = (b === 0 ? -1 : 1) * (0.4 + rk() * 0.6);
        grow(cx, cy, ang + da, len * (0.72 + rk() * 0.14), wdt * 0.66, depth + 1, cd);
      }
    }
    const nPrim = 4 + Math.floor(rk() * 3);
    for (let p2 = 0; p2 < nPrim; p2++) {
      const a0 = p2 / nPrim * 6.2831853 + rk() * 0.5;
      grow(0, 0, a0, 0.2 + rk() * 0.06, 0.05, 0, 0);
    }
    // axon: a long meandering path in one direction, with boutons
    const axDir = rk() * 6.2831853;
    let ax = 0, ay = 0, aa = axDir, ad = 0;
    const axLen = 0.9 + rk() * 0.7, seg = 0.12;
    for (let s2 = 0; s2 * seg < axLen; s2++) {
      aa += (rk() - 0.5) * 0.5;
      const nx = ax + Math.cos(aa) * seg, ny = ay + Math.sin(aa) * seg;
      segs.push({ x1: ax, y1: ay, x2: nx, y2: ny, w: 0.028, d0: ad, d1: ad + seg, axon: 1 });
      ad += seg; ax = nx; ay = ny;
      if (s2 % 2 === 1) boutons.push({ x: nx, y: ny, d: ad });
      if (ad > maxd) maxd = ad;
    }
    S.cells.push({
      cx: 0.12 + fr(k * 13 + 3) * 0.76, cy: 0.14 + fr(k * 17 + 4) * 0.72,
      rad: 0.14 + fr(k * 19 + 5) * 0.14,
      segs, boutons, maxd,
      foff: fr(k * 23 + 6), frate: 0.16 + fr(k * 29 + 7) * 0.14,
      sway: fr(k * 31 + 8) * 6.283,
      hueJ: (fr(k * 37 + 9) - 0.5) * 34,
      dph: fr(k * 41 + 10) * 6.283, drate: 0.03 + fr(k * 43 + 11) * 0.05
    });
  }
  // neuropil: faint out-of-focus background processes
  S.neuro = [];
  const nn = 90 + Math.round(P.density * 80);
  for (let k = 0; k < nn; k++) S.neuro.push({ x: fr(k * 3 + 201), y: fr(k * 5 + 202), a: fr(k * 7 + 203) * 6.283, l: 0.02 + fr(k * 11 + 204) * 0.05, ph: fr(k * 13 + 205) * 6.283, br: 0.3 + fr(k * 17 + 206) * 0.6 });
}

const t = K.t;
const style = P.style;
const glow = 0.4 + P.energy * 1.3 + A.rms * 0.35;

let bgH, bgS, bgB, mode;
if (style === 'golgi') { bgH = 36; bgS = 22; bgB = 68; mode = 'golgi'; }
else if (style === 'neon') { bgH = 268; bgS = 40; bgB = 8; mode = 'neon'; }
else if (style === 'schematic') { bgH = 214; bgS = 60; bgB = 22; mode = 'schematic'; }
else { bgH = 155; bgS = 45; bgB = 8; mode = 'fluor'; }
const pale = (mode === 'golgi');

push();
noStroke(); rectMode(CENTER);
fill(bgH, bgS, bgB); rect(width / 2, height / 2, width * 1.02, height * 1.02);
// faint condenser lift
for (let ri = 5; ri >= 1; ri--) { const rr = u * (0.35 + ri * 0.14); if (pale) fill(bgH, bgS * 0.6, bgB + (6 - ri) * 2.4 * (0.7 + glow * 0.3), 22); else fill(bgH, bgS * 0.6, Math.min(60, bgB + (6 - ri) * 2.6), 16); ellipse(width * 0.5, height * 0.5, rr * 2.2, rr * 2); }

// neuropil haze (broad low-alpha element carrying luminance + drift) ----------
strokeCap(ROUND);
for (let k = 0; k < S.neuro.length; k++) {
  const p = S.neuro[k];
  const dx = (p.x + 0.02 * Math.sin(t * 0.05 * sp + p.ph)) * width;
  const dy = (p.y + 0.02 * Math.cos(t * 0.045 * sp + p.ph)) * height;
  const b = p.br * (0.5 + 0.5 * Math.sin(t * 0.4 + p.ph * 2));
  strokeWeight(Math.max(0.6, u * 0.003));
  if (pale) stroke(bgH, 24, 40 + b * 16, 18);
  else stroke((P.hue + 20) % 360, 40, 14 + b * 16, 26);
  const ll = p.l * u;
  line(dx, dy, dx + Math.cos(p.a) * ll, dy + Math.sin(p.a) * ll);
}

if (mode === 'fluor' || mode === 'neon') blendMode(ADD);

for (let ci = 0; ci < S.cells.length; ci++) {
  const c = S.cells[ci];
  const R = c.rad * u * P.scale;
  const swx = Math.sin(t * c.drate * sp + c.dph) * u * 0.012;
  const swy = Math.cos(t * (c.drate * 0.8) * sp + c.dph) * u * 0.012;
  const ox = c.cx * width + swx, oy = c.cy * height + swy;
  const hue = (P.hue + c.hueJ + 360) % 360;
  // firing wave front travels outward, looping -> perpetual back-propagation
  const front = ((t * c.frate * sp * fireRate) % 1) * c.maxd * 1.15;
  const somaFlash = Math.max(0, Math.exp(-Math.pow(((t * c.frate * sp * fireRate) % 1) - 0.02, 2) * 40));
  const spread = c.maxd * 0.16 + 0.06;

  push(); translate(ox, oy);
  // slight arbor sway
  const swa = Math.sin(t * 0.3 * sp + c.sway) * 0.03;
  rotate(swa);

  // dendrites + axon
  for (let s2 = 0; s2 < c.segs.length; s2++) {
    const g2 = c.segs[s2];
    const md = (g2.d0 + g2.d1) * 0.5;
    const wave = Math.exp(-Math.pow((md - front) / spread, 2));   // AP/Ca transient
    let b, sat, hh = hue;
    if (pale) { b = 16 + (1 - wave) * 6 + wave * 4; sat = 30; hh = 34; }         // Golgi: near-black ink, faint focus shimmer
    else if (mode === 'schematic') { b = 55 + wave * 40; sat = 26; hh = 205; }
    else { b = (g2.axon ? 22 : 30) + wave * 55 * fireRate + somaFlash * 25; b = Math.min(100, b * (0.7 + glow * 0.5)); sat = mode === 'neon' ? 80 : 66; hh = (hue + (g2.axon ? 30 : 0)) % 360; }
    strokeWeight(Math.max(0.5, R * g2.w * (g2.axon ? 1.1 : 1.5) * (1 + wave * 0.5)));
    stroke(hh, sat, b, pale ? 88 : (60 + wave * 35));
    line(g2.x1 * R, g2.y1 * R, g2.x2 * R, g2.y2 * R);
  }
  // boutons flash as the spike passes
  noStroke();
  for (let b2 = 0; b2 < c.boutons.length; b2++) {
    const bt = c.boutons[b2];
    const wave = Math.exp(-Math.pow((bt.d - front) / (spread * 0.6), 2));
    const br = pale ? 20 : Math.min(100, (26 + wave * 70 * fireRate) * (0.7 + glow * 0.5));
    fill(pale ? 34 : (hue + 40) % 360, pale ? 30 : 70, br, pale ? 85 : (40 + wave * 55));
    const sz = R * (0.035 + wave * 0.05);
    ellipse(bt.x * R, bt.y * R, sz, sz);
  }
  // soma with nucleus
  noStroke();
  const sB = pale ? 14 : Math.min(100, (34 + somaFlash * 55) * (0.7 + glow * 0.5));
  if (!pale) for (let g3 = 3; g3 >= 1; g3--) { fill(hue, 60, sB, mode === 'schematic' ? 60 : (18 + somaFlash * 22)); ellipse(0, 0, R * (0.22 + g3 * 0.07), R * (0.22 + g3 * 0.07)); }
  fill(pale ? 34 : hue, pale ? 34 : 55, sB, pale ? 90 : 70); ellipse(0, 0, R * 0.24, R * 0.22);
  fill(pale ? 34 : (hue + 20) % 360, pale ? 20 : 40, pale ? 30 : Math.min(100, sB * 0.7), pale ? 70 : 55); ellipse(R * 0.03, -R * 0.02, R * 0.1, R * 0.1);  // nucleus/nucleolus
  pop();
}
if (mode === 'fluor' || mode === 'neon') blendMode(BLEND);

pop();
if (P.alpha < 100) { push(); noStroke(); rectMode(CORNER); fill(bgH, bgS, bgB, 100 - Math.max(0, Math.min(100, P.alpha))); rect(0, 0, width, height); pop(); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
